		//Paso 1: Leer las entradas del agente de alquiler de autos
		Scanner scan = new Scanner(System.in);
		System.out.println("Ingrese la edad del cliente:");
		int age = scan.nextInt();
		System.out.println("Indique si el cliente tiene licencia de conducir (true o false):");
		boolean hasLicense = scan.nextBoolean();			
